SELECT version();
-- shell: gs_om -t status
-- shell: gs_om -t status --detail

SELECT datname, pg_size_pretty(pg_database_size(datname)) AS size,
  (SELECT count(*) FROM pg_stat_activity a WHERE a.datid = d.oid) AS connections
FROM pg_database d ORDER BY pg_database_size(datname) DESC;

-- 1. 先确认统计信息是否过期（只读）：
SELECT schemaname, relname, last_analyze, last_autoanalyze, n_mod_since_analyze
FROM pg_stat_user_tables WHERE schemaname = '<SCHEMA>' AND relname = '<TABLE>';
-- 2. 确认后再执行（建议非高峰）：
-- DANGER: ANALYZE <SCHEMA>.<TABLE>;

-- 正在等待锁的会话（官方手册示例：pg_stat_activity WHERE waiting = true）：
SELECT datname, usename, pid, state, waiting, now() - query_start AS wait_duration, left(query, 200) AS query
FROM pg_stat_activity WHERE waiting = true ORDER BY query_start;
-- 锁持有情况：
SELECT locktype, mode, granted, count(*) AS cnt FROM pg_locks GROUP BY locktype, mode, granted ORDER BY cnt DESC;

-- 1. 先确认（只读查询）：
SELECT datid, pid, usename, state, left(query, 200) AS query FROM pg_stat_activity WHERE pid = <PID>;
-- 2. 确认无误后再执行（危险）：
-- DANGER: SELECT pg_terminate_backend(<PID>);

SELECT spcname, pg_size_pretty(pg_tablespace_size(spcname)) AS size,
  pg_tablespace_location(oid) AS location
FROM pg_tablespace ORDER BY pg_tablespace_size(spcname) DESC;

-- 1. 先查看现有用户与属性（只读）：
SELECT rolname, rolsuper, rolcreaterole, rolcreatedb, rolcanlogin, rolvaliduntil FROM pg_roles ORDER BY rolname;
-- 2. 新建用户（模板，密码须符合 openGauss 复杂度要求）：
-- DANGER: CREATE USER <USERNAME> WITH PASSWORD '<PASSWORD>';
-- 3. 授权示例：
-- DANGER: GRANT SELECT ON <SCHEMA>.<TABLE> TO <USERNAME>;
